using System;using System.Collections.Generic;using UnityEngine.InputSystem;using UnityEngine;using UnityEngine.UI;using UnityEngine.EventSystems;using UnityEngine.InputSystem.UI;using UnityEngine.SceneManagement;
public sealed class TrainingFrontMenu:MonoBehaviour {
 public FighterCatalog catalog;public string supportedTrainingFighterId;
 public bool FighterSelectionVisible{get;private set;}public string SelectedId{get;private set;}public string Status{get;private set;}public bool Starting{get;private set;}
 public Camera MenuCamera{get;private set;}public event Action TrainingRequested;public bool SuppressSceneLoadForTests{get;set;}
 PlayerPreferencesStore store;TrainingMenuInput input;GameObject canvasObject,ownedEvents;RectTransform panel;Text title,note;Font font;readonly List<Button> buttons=new List<Button>();int focus;bool ready;
 public void UseStoreForTests(PlayerPreferencesStore isolated){store=isolated;if(ready){var preferences=store.Load(catalog.FirstId,out var state);TrainingFlow.TryPrepare(catalog,preferences,out var request,out var resolved);SelectedId=request.fighterId;Status=state+" / "+resolved;input?.Dispose();input=new TrainingMenuInput();Build();}}
 void Start(){store=store??new PlayerPreferencesStore();input=new TrainingMenuInput();font=Font.CreateDynamicFontFromOSFont(new[]{"Yu Gothic","Meiryo","Arial"},22);canvasObject=new GameObject("Title and fighter selection",typeof(RectTransform),typeof(Canvas),typeof(CanvasScaler),typeof(GraphicRaycaster));canvasObject.transform.SetParent(transform,false);var canvas=canvasObject.GetComponent<Canvas>();var cameraObject=new GameObject("Menu camera",typeof(Camera));cameraObject.transform.SetParent(transform,false);cameraObject.transform.position=new Vector3(0,0,-10);MenuCamera=cameraObject.GetComponent<Camera>();MenuCamera.orthographic=true;MenuCamera.nearClipPlane=.1f;MenuCamera.farClipPlane=100;MenuCamera.clearFlags=CameraClearFlags.SolidColor;MenuCamera.backgroundColor=Color.black;canvas.renderMode=RenderMode.ScreenSpaceCamera;canvas.worldCamera=MenuCamera;canvas.planeDistance=1;canvas.sortingOrder=200;var scaler=canvasObject.GetComponent<CanvasScaler>();scaler.uiScaleMode=CanvasScaler.ScaleMode.ScaleWithScreenSize;scaler.referenceResolution=new Vector2(1080,700);scaler.matchWidthOrHeight=.5f;
 var backdrop=new GameObject("Backdrop",typeof(RectTransform),typeof(Image));backdrop.transform.SetParent(canvasObject.transform,false);var r=(RectTransform)backdrop.transform;r.anchorMin=Vector2.zero;r.anchorMax=Vector2.one;r.offsetMin=r.offsetMax=Vector2.zero;backdrop.GetComponent<Image>().color=new Color(.035f,.055f,.065f,1);
 var body=new GameObject("Menu",typeof(RectTransform));body.transform.SetParent(canvasObject.transform,false);panel=(RectTransform)body.transform;panel.anchorMin=panel.anchorMax=panel.pivot=new Vector2(.5f,.5f);panel.sizeDelta=new Vector2(760,620);
 title=Label("Title",40,new Vector2(0,245),new Vector2(730,65));note=Label("Status",19,new Vector2(0,-230),new Vector2(730,150));
 if(EventSystem.current==null){ownedEvents=new GameObject("Menu EventSystem",typeof(EventSystem),typeof(InputSystemUIInputModule));ownedEvents.transform.SetParent(transform,false);ownedEvents.GetComponent<EventSystem>().sendNavigationEvents=false;}
 string error="Fighter catalog missing";if(catalog==null||!catalog.Validate(out error)){Status=catalog==null?"Fighter catalog missing":error;ready=true;Build();return;}var preferences=store.Load(catalog.FirstId,out var state);TrainingFlow.TryPrepare(catalog,preferences,out var request,out var resolved);SelectedId=request.fighterId;Status=state+" / "+resolved;ready=true;Build();}
 Text Label(string name,int size,Vector2 pos,Vector2 dimensions){var go=new GameObject(name,typeof(RectTransform),typeof(Text));go.transform.SetParent(panel,false);var t=go.GetComponent<Text>();t.font=font;t.fontSize=size;t.color=Color.white;t.alignment=TextAnchor.MiddleCenter;t.raycastTarget=false;t.rectTransform.anchoredPosition=pos;t.rectTransform.sizeDelta=dimensions;return t;}
 void Build(){foreach(var b in buttons){b.gameObject.SetActive(false);Destroy(b.gameObject);}buttons.Clear();focus=0;title.text=FighterSelectionVisible?"Fighter select":"Shioka";if(catalog!=null&&catalog.Validate(out _)){if(!FighterSelectionVisible)Add("Training",OpenFighterSelect,true);else{foreach(var prefab in catalog.fighters){var character=FighterCatalog.Character(prefab);string id=character.characterId;bool supported=id==supportedTrainingFighterId;Add((id==SelectedId?"✓ ":"")+character.characterName+(supported?"":" (not connected)"),()=>SelectFighter(id),supported);}Add("Training開始 / 保存",StartTraining,SelectedId==supportedTrainingFighterId);Add("戻る",Back,true);}}
 note.text=DisplayStatus()+"\n"+(FighterSelectionVisible?"キャラ選択はTraining開始時に保存します。\n":"Trainingを選ぶとキャラ選択へ進みます。\n")+"W/S・Dpad: 選択  Mouse: click\n決定: "+MenuBinding("menu.Confirm")+"   戻る: "+MenuBinding("menu.Cancel")+" / "+MenuBinding("common.Options");for(int i=0;i<buttons.Count;i++)((RectTransform)buttons[i].transform).anchoredPosition=new Vector2(0,100-i*65);if(buttons.Count>0){while(focus<buttons.Count-1&&!buttons[focus].interactable)focus++;Highlight();}input?.Clear();}
 string DisplayStatus(){if(string.IsNullOrEmpty(Status))return "";if(Status.StartsWith("Save failed"))return "保存できません。選択はまだ反映されていません。";if(Status.Contains("Unavailable fighter"))return "保存したキャラが見つからないため、既定のキャラを表示しています。";if(Status.Contains("Read fallback"))return "保存設定を読めないため、既定のキャラを表示しています。";if(Status.Contains("Selected fighter resolved"))return "";return Status;}
 string MenuBinding(string id){var row=KeyConfigService.Ensure().Row(id);return Binding(row.keyboard)+" / "+Binding(row.pad);}
 static string Binding(string value){if(string.IsNullOrEmpty(value))return "—";int modifier=KeyConfigProfile.Modifier(value);return (modifier==0?"":"T"+modifier+"+")+InputControlPath.ToHumanReadableString(KeyConfigProfile.PathPart(value),InputControlPath.HumanReadableStringOptions.OmitDevice);}
 void Add(string text,Action action,bool enabled){var go=new GameObject(text,typeof(RectTransform),typeof(Image),typeof(Button));go.transform.SetParent(panel,false);var r=(RectTransform)go.transform;r.sizeDelta=new Vector2(610,52);var button=go.GetComponent<Button>();button.interactable=enabled;button.navigation=new Navigation{mode=Navigation.Mode.None};var label=new GameObject("Label",typeof(RectTransform),typeof(Text));label.transform.SetParent(go.transform,false);var t=label.GetComponent<Text>();t.font=font;t.fontSize=25;t.alignment=TextAnchor.MiddleCenter;t.color=enabled?Color.white:Color.gray;t.raycastTarget=false;var lr=t.rectTransform;lr.anchorMin=Vector2.zero;lr.anchorMax=Vector2.one;lr.offsetMin=lr.offsetMax=Vector2.zero;t.text=text;buttons.Add(button);button.onClick.AddListener(()=>{focus=buttons.IndexOf(button);action();});}
 void Highlight(){for(int i=0;i<buttons.Count;i++)buttons[i].GetComponent<Image>().color=i==focus?new Color(.15f,.48f,.48f):new Color(.1f,.19f,.2f);if(buttons.Count>0&&EventSystem.current!=null)EventSystem.current.SetSelectedGameObject(buttons[focus].gameObject);}
 void Update(){if(!ready||Starting||input==null)return;var frame=input.Read();if(frame.cancel||frame.option){Back();return;}if(frame.direction.y!=0&&buttons.Count>0){int direction=frame.direction.y>0?-1:1;for(int n=0;n<buttons.Count;n++){focus=(focus+direction+buttons.Count)%buttons.Count;if(buttons[focus].interactable)break;}Highlight();}if(frame.confirm&&buttons.Count>0&&buttons[focus].interactable)buttons[focus].onClick.Invoke();}
 public void OpenFighterSelect(){FighterSelectionVisible=true;Build();}public void SelectFighter(string id){if(catalog==null||id!=supportedTrainingFighterId||catalog.Find(id)==null)return;SelectedId=id;Build();}
 public void Back(){if(!FighterSelectionVisible){input?.Clear();return;}FighterSelectionVisible=false;Build();}
 public void StartTraining(){if(Starting||SelectedId!=supportedTrainingFighterId)return;var preference=new PlayerPreferences{selectedFighterId=SelectedId};if(!TrainingFlow.TryPrepare(catalog,preference,out var request,out var status)||request.fighterId!=supportedTrainingFighterId){Status=status;Build();return;}if(!store.Save(preference,out var error)){Status=error;Build();return;}Starting=true;TrainingFlowSession.AwaitingTrainingEntry=true;input.Clear();TrainingRequested?.Invoke();if(!SuppressSceneLoadForTests){Time.timeScale=1;SceneManager.LoadScene(TrainingFlowSession.TrainingScene);}}
 void OnApplicationFocus(bool focused){if(!focused)input?.Clear();}void OnDestroy(){input?.Dispose();if(font!=null)Destroy(font);}
}
